<?php
declare(strict_types=1);
if($page==='engineer-find') {
    auth('engineer');page_start('Join a project',true);
    echo '<div class="page-head"><div><span class="eyebrow">SITE ENGINEER</span><h1>Join a project by code</h1><p>Enter the code shared by your Project Manager. You must belong to the same NGO to join.</p></div></div>';
    echo '<div class="content-card narrow-card"><form class="form-stack" method="post">'.csrf_input().'<input type="hidden" name="action" value="engineer_join"><div class="field"><label for="projectCode">Six-character project code</label><input id="projectCode" name="project_code" maxlength="6" minlength="6" pattern="[A-Za-z2-9]{6}" placeholder="FRSW23" required autocomplete="off"></div><button class="btn">Join assigned NGO project</button></form></div>';
    page_end(true);
} elseif($page==='engineer-chats') {
    auth(['manager','engineer']);
    if(role()==='manager')$threads=all("SELECT p.id project_id,p.title,p.project_code,u.id engineer_id,u.full_name engineer_name FROM project_engineers pe JOIN projects p ON p.id=pe.project_id JOIN users u ON u.id=pe.engineer_id WHERE p.manager_id=? AND p.ngo_id=? AND u.is_active=1 ORDER BY p.title,u.full_name",[uid(),ngo_id()]);
    else $threads=all("SELECT p.id project_id,p.title,p.project_code,u.id engineer_id,u.full_name engineer_name FROM project_engineers pe JOIN projects p ON p.id=pe.project_id JOIN users u ON u.id=pe.engineer_id WHERE pe.engineer_id=? AND p.ngo_id=? ORDER BY p.title",[uid(),ngo_id()]);
    page_start('Site messages',true);echo '<div class="page-head"><div><span class="eyebrow">PROJECT TEAM</span><h1>Site Engineer and Project Manager messages</h1><p>Messages are available only to the assigned Site Engineer and Project Manager.</p></div></div><div class="content-card">';
    if(!$threads)echo '<p class="muted">No site-team conversations are available. Join or assign a project first.</p>';
    foreach($threads as $t)echo '<div class="client-line"><div><strong>'.e($t['title']).'</strong><p>'.e($t['engineer_name']).' · '.e($t['project_code']).'</p></div><a class="btn btn-small btn-outline" href="'.url('engineer-chat',['id'=>$t['project_id'],'engineer'=>$t['engineer_id']]).'">Open conversation</a></div>';
    echo '</div>';page_end(true);
} elseif($page==='engineer-chat') {
    auth(['manager','engineer']);$p=need_project($id);$eid=role()==='engineer'?uid():max(0,(int)($_GET['engineer']??0));
    if(!engineer_can_message($p,$eid)){http_response_code(403);page_start('Access denied');echo '<div class="content-card">This conversation is not available to your account.</div>';page_end();exit;}
    $partner=one('SELECT full_name FROM users WHERE id=?',[$eid]);$messages=all('SELECT m.*,u.full_name sender_name FROM engineer_messages m JOIN users u ON u.id=m.sender_id WHERE m.project_id=? AND m.engineer_id=? ORDER BY m.id ASC LIMIT 500',[$id,$eid]);
    page_start('Site messages',true);echo '<div class="page-head"><div><span class="eyebrow">PRIVATE PROJECT CHAT</span><h1>'.e($p['title']).'</h1><p>'.(role()==='manager'?'Site Engineer: '.e($partner['full_name']??'Site Engineer'):'Chat with your Project Manager').'</p></div></div><div class="content-card chat-box">';
    if(!$messages)echo '<p class="muted">No messages have been sent in this conversation.</p>';
    foreach($messages as $m)echo '<div class="chat-bubble '.((int)$m['sender_id']===uid()?'chat-me':'chat-other').'"><strong>'.e($m['sender_name']).'</strong><p>'.nl2br(e($m['body'])).'</p><small>'.e($m['created_at']).'</small></div>';
    echo '<form method="post" class="form-stack chat-form">'.csrf_input().'<input type="hidden" name="action" value="engineer_message_send"><input type="hidden" name="project_id" value="'.$id.'"><input type="hidden" name="engineer_id" value="'.$eid.'"><div class="field"><label for="siteMessage">Your message</label><textarea id="siteMessage" name="body" rows="4" maxlength="3000" required></textarea></div><button class="btn">Send message</button></form></div>';page_end(true);
} elseif($page==='support') {
    auth();$tickets=all('SELECT * FROM support_tickets WHERE user_id=? ORDER BY created_at DESC LIMIT 50',[uid()]);
    page_start('Account support',true);
    echo '<div class="page-head"><div><span class="eyebrow">ACCOUNT SUPPORT</span><h1>Contact the Super Admin</h1><p>Use this page for account access, incorrect figures, or technical problems. For project discussions, use the Project Manager messaging page.</p></div></div><div class="content-card narrow-card"><h2>Submit a support request</h2><form method="post" class="form-stack">'.csrf_input().'<input type="hidden" name="action" value="support_send"><div class="field"><label>Subject</label><input name="subject" maxlength="190" minlength="3" required></div><div class="field"><label>Explain the problem</label><textarea name="body" rows="5" maxlength="3000" minlength="10" required></textarea></div><button class="btn">Send to Super Admin</button></form></div><div class="content-card"><h2>My support requests</h2>';
    foreach($tickets as $tick)echo '<div class="client-line"><div><strong>'.e($tick['subject']).'</strong><p>'.nl2br(e($tick['body'])).'</p><small>'.e($tick['created_at']).' · '.e($tick['status']).'</small>'.($tick['owner_reply']?'<p><strong>Super Admin reply:</strong> '.nl2br(e($tick['owner_reply'])).'</p>':'').'</div></div>';
    if(!$tickets)echo '<p>No support requests have been submitted.</p>';
    echo '</div>';page_end(true);
} elseif($page==='admin-oversight') {
    auth('super_admin');$projects=all("SELECT p.id,p.title,p.project_code,p.budget_total,p.ngo_id,n.name ngo_name,u.full_name manager_name FROM projects p JOIN ngos n ON n.id=p.ngo_id JOIN users u ON u.id=p.manager_id ORDER BY n.name,p.title LIMIT 300");
    $events=all("SELECT ae.*,u.full_name actor_name,u.role actor_role,p.title project_title FROM audit_events ae JOIN users u ON u.id=ae.user_id LEFT JOIN projects p ON p.id=ae.project_id ORDER BY ae.id DESC LIMIT 250");
    $financial=all("SELECT f.*,p.title project_title,n.name ngo_name,u.full_name entered_name FROM project_finances f JOIN projects p ON p.id=f.project_id JOIN ngos n ON n.id=p.ngo_id JOIN users u ON u.id=f.entered_by ORDER BY f.id DESC LIMIT 200");
    $users=all("SELECT id,full_name,email,deleted_at FROM users WHERE role<>'super_admin' ORDER BY id DESC LIMIT 300");
    page_start('Owner oversight',true);
    echo '<div class="page-head"><div><span class="eyebrow">SUPER ADMIN CONTROL</span><h1>Project budgets, account control and audit log</h1><p>Only the owner can view all NGOs and record corrections. Changes are logged and old entries remain traceable.</p></div></div>';
    $managers=all("SELECT id,full_name,ngo_id FROM users WHERE role='manager' AND is_active=1 AND deleted_at IS NULL ORDER BY full_name");
    echo '<div class="content-card"><h2>Transfer a project to another Project Manager</h2><p class="muted">Transfer a project before converting its former manager to Site Engineer. Managers must belong to the same NGO as the project.</p><form class="form-stack" method="post">'.csrf_input().'<input type="hidden" name="action" value="admin_transfer_project"><div class="form-row"><div class="field"><label>Project</label><select name="project_id" required><option value="">Choose a project</option>';
    foreach($projects as $pr)echo '<option value="'.(int)$pr['id'].'">'.e($pr['ngo_name'].' · '.$pr['title']).'</option>';
    echo '</select></div><div class="field"><label>New Project Manager</label><select name="manager_id" required><option value="">Choose a manager in the same NGO</option>';
    foreach($managers as $mgr)echo '<option value="'.(int)$mgr['id'].'">'.e($mgr['full_name']).' (NGO #'.(int)$mgr['ngo_id'].')</option>';
    echo '</select></div></div><div class="field"><label>Reason for transfer</label><input name="reason" minlength="5" maxlength="500" required></div><button class="btn">Transfer project</button></form></div>';
    echo '<div class="content-card"><h2>Correct project budgets and confirmed activities</h2><form method="post" class="form-stack">'.csrf_input().'<input type="hidden" name="action" value="admin_budget_adjust"><div class="field"><label>Project</label><select name="project_id" required><option value="">Select project</option>';
    foreach($projects as $pr)echo '<option value="'.(int)$pr['id'].'">'.e($pr['ngo_name'].' — '.$pr['title']).'</option>';
    echo '</select></div><div class="field"><label>Correct approved project budget (NGN)</label><input name="budget_total" type="number" step="0.01" min="0" required></div><div class="field"><label>Reason for correction</label><input name="reason" minlength="5" maxlength="500" required></div><button class="btn">Correct project budget</button></form>';
    echo '<hr><form method="post" class="form-stack">'.csrf_input().'<input type="hidden" name="action" value="admin_activity_fix"><div class="field"><label>Activity</label><select name="activity_id" id="ownerActivity" required><option value="">Select activity</option>';
    $allActivities=all('SELECT a.id,a.title,p.id project_id,p.title project_title FROM activities a JOIN projects p ON p.id=a.project_id WHERE a.deleted_at IS NULL ORDER BY p.title,a.title LIMIT 1000');
    foreach($allActivities as $a)echo '<option value="'.(int)$a['id'].'" data-project="'.(int)$a['project_id'].'">'.e($a['project_title'].' — '.$a['title']).'</option>';
    echo '</select></div><div class="field"><label>Project ID for the selected activity</label><input type="number" name="project_id" id="ownerActivityProject" min="1" required></div><div class="field"><label>Correct status</label><select name="new_status"><option value="pending">Not confirmed</option><option value="approved">Confirmed complete</option></select></div><div class="field"><label>Reason for correction</label><input name="reason" minlength="5" maxlength="500" required></div><button class="btn btn-outline">Correct activity status</button></form></div>';
    echo '<div class="content-card"><h2>Delete an activity</h2><p class="muted">The Super Admin can delete an activity from any NGO, including approved work. This removes it from progress, project pages and client reports but retains photographs and the audit history.</p><form method="post" class="form-stack">'.csrf_input().'<input type="hidden" name="action" value="activity_archive"><input type="hidden" name="return_to" value="admin-oversight"><div class="field"><label>Active activity</label><select name="activity_id" required><option value="">Choose an activity</option>';
    foreach($allActivities as $a)echo '<option value="'.(int)$a['id'].'">'.e($a['project_title'].' — '.$a['title']).'</option>';
    echo '</select></div><div class="field"><label>Reason for removal</label><input name="reason" minlength="5" maxlength="500" required></div><label class="checkline"><input type="checkbox" name="confirm_archive" value="1" required> I understand that this may reduce confirmed project progress.</label><button class="btn btn-danger">Delete activity</button></form></div>';
    $archived=all('SELECT a.id,a.title,a.weight_percent,a.delete_reason,a.deleted_at,p.title project_title,u.full_name removed_by FROM activities a JOIN projects p ON p.id=a.project_id LEFT JOIN users u ON u.id=a.deleted_by WHERE a.deleted_at IS NOT NULL ORDER BY a.deleted_at DESC,a.id DESC LIMIT 100');
    echo '<div class="content-card"><h2>Deleted activities and restoration</h2><p class="muted">Deleted activities stay available to the Super Admin for auditing. Restored activities return as pending and need new confirmation. Restoration is blocked if the active activity weights would exceed 100%.</p>';
    if(!$archived)echo '<p class="muted">No deleted activities.</p>';
    foreach($archived as $a)echo '<div class="activity-action"><strong>'.e($a['project_title'].' — '.$a['title']).'</strong><p class="small muted">Weight: '.number_format((float)$a['weight_percent'],2).'% · Deleted: '.e($a['deleted_at']).' · By: '.e($a['removed_by']??'Unknown').'</p><p class="small muted">Reason: '.e($a['delete_reason']??'Not recorded').'</p><form method="post" class="form-stack">'.csrf_input().'<input type="hidden" name="action" value="activity_restore"><input type="hidden" name="activity_id" value="'.(int)$a['id'].'"><div class="field"><label>Reason to restore</label><input name="reason" minlength="5" maxlength="500" required></div><button class="btn btn-small btn-outline">Restore activity as pending</button></form></div>';
    echo '</div>';
    $tickets=all('SELECT t.*,u.full_name,u.role,u.email FROM support_tickets t JOIN users u ON u.id=t.user_id ORDER BY (t.status="open") DESC,t.id DESC LIMIT 100');
    echo '<div class="content-card"><h2>Support requests from all roles</h2>';
    if(!$tickets)echo '<p>No support requests submitted.</p>';
    foreach($tickets as $ticket){echo '<div class="activity-action"><strong>'.e($ticket['subject']).'</strong><p>'.e($ticket['full_name']).' · '.e(role_label($ticket['role'])).' · '.e($ticket['created_at']).'</p><p>'.nl2br(e($ticket['body'])).'</p><small>'.e($ticket['status']).'</small>';
        if($ticket['status']==='open')echo '<form method="post" class="form-stack">'.csrf_input().'<input type="hidden" name="action" value="support_resolve"><input type="hidden" name="ticket_id" value="'.(int)$ticket['id'].'"><div class="field"><label>Response</label><textarea name="owner_reply" rows="2" minlength="3" maxlength="3000" required></textarea></div><button class="btn btn-small">Respond and resolve</button></form>';
        else echo '<p><strong>Owner reply:</strong> '.nl2br(e($ticket['owner_reply']??'')).'</p>';
        echo '</div>';}
    echo '</div>';
    echo '<div class="content-card"><h2>All NGO project budgets</h2><div class="table-wrap"><table><thead><tr><th>NGO and project</th><th>Manager</th><th>Budget</th><th>Approved spending</th><th>Pending spending</th><th>Balance</th></tr></thead><tbody>';
    foreach($projects as $p){$f=project_finance((int)$p['id']);echo '<tr><td><a href="'.url('project',['id'=>$p['id']]).'">'.e($p['title']).'</a><span class="table-sub">'.e($p['ngo_name']).' · '.e($p['project_code']).'</span></td><td>'.e($p['manager_name']).'</td><td>'.money($f['budget_total']).'</td><td>'.money($f['expenses']).'</td><td>'.money(pending_expense_total((int)$p['id'])).'</td><td>'.money($f['remaining']).'</td></tr>';}
    echo '</tbody></table></div></div>';
    echo '<div class="content-card"><h2>Correct an incorrect financial entry</h2><p class="muted">Void an entry below and add a corrected amount with a clear reason. The previous entry stays in the audit trail.</p><form class="form-stack" method="post">'.csrf_input().'<input type="hidden" name="action" value="admin_finance_correct"><div class="field"><label>Project</label><select name="project_id" required><option value="">Select project</option>';
    foreach($projects as $p)echo '<option value="'.(int)$p['id'].'">'.e($p['ngo_name'].' — '.$p['title']).'</option>';
    echo '</select></div><div class="form-row"><div class="field"><label>Record type</label><select name="entry_type"><option value="expense">Expense</option><option value="funding">Funding</option></select></div><div class="field"><label>Correct amount (NGN)</label><input name="amount" type="number" step="0.01" min="0.01" required></div></div><div class="field"><label>Transaction date</label><input name="entry_date" type="date" value="'.date('Y-m-d').'" required></div><div class="field"><label>Description</label><input name="description" maxlength="255" required></div><div class="field"><label>Reason for correction</label><input name="reason" minlength="5" maxlength="500" required></div><button class="btn">Add audited correction</button></form></div>';
    echo '<div class="content-card"><h2>Financial ledger across all NGOs</h2><div class="table-wrap"><table><thead><tr><th>Project</th><th>Date</th><th>Recorded by</th><th>Type and description</th><th>Amount</th><th>Approval</th><th>Owner action</th></tr></thead><tbody>';
    foreach($financial as $f){echo '<tr><td>'.e($f['ngo_name'].' / '.$f['project_title']).'</td><td>'.e($f['entry_date']).'</td><td>'.e($f['entered_name']).'</td><td>'.e($f['entry_type'].' — '.$f['description']).'</td><td>'.money($f['amount']).'</td><td>'.e($f['approval_status']).'</td><td>';
        if($f['approval_status']==='approved')echo '<form method="post" class="form-stack">'.csrf_input().'<input type="hidden" name="action" value="admin_finance_void"><input type="hidden" name="finance_id" value="'.(int)$f['id'].'"><input name="reason" placeholder="Correction reason" minlength="5" maxlength="500" required><button class="btn btn-small btn-danger">Void entry</button></form>';
        echo '</td></tr>';}
    echo '</tbody></table></div></div>';
    echo '<div class="content-card"><h2>Account removal and restoration</h2><p class="muted">Removing an account disables its login rather than erasing its project history and audit records.</p>';
    foreach($users as $u)echo '<div class="client-line"><div><strong>'.e($u['full_name']).'</strong><p>'.e($u['email']).' · '.($u['deleted_at']?'Removed':'Active or suspended').'</p></div><form class="form-row" method="post">'.csrf_input().'<input type="hidden" name="action" value="'.($u['deleted_at']?'admin_account_restore':'admin_account_delete').'"><input type="hidden" name="user_id" value="'.(int)$u['id'].'"><input name="reason" placeholder="Required reason" minlength="5" maxlength="500" required><button class="btn btn-small '.($u['deleted_at']?'btn-outline':'btn-danger').'">'.($u['deleted_at']?'Restore':'Remove').'</button></form></div>';
    echo '</div>';
    echo '<div class="content-card"><h2>Latest activity logs for all roles</h2><div class="table-wrap"><table><thead><tr><th>Time</th><th>User / role</th><th>Project</th><th>Action</th><th>Details</th></tr></thead><tbody>';
    foreach($events as $ev)echo '<tr><td>'.e($ev['created_at']).'</td><td>'.e($ev['actor_name']).'<span class="table-sub">'.e(role_label($ev['actor_role'])).'</span></td><td>'.e($ev['project_title']??'—').'</td><td>'.e($ev['action']).'</td><td>'.e($ev['details']).'</td></tr>';
    echo '</tbody></table></div></div>';page_end(true);
}
